"""Check a prepared cross-feature endpoint without fitting a road-to-road join.

The other feature may have no surface provider or editable source object yet.
Its original identity remains an explicit boundary declaration. This validates
the declaration and the road's live terminal edge; it does not claim a welded
or smooth road/footway surface across independently owned features.
"""
from . import curved_corner_nodes as c
from . import curved_junction_nodes as boundary
from .curved_network_ownership_nodes import _compare


def valid(g, sources, spans, span, reverse, role, owner, next_section, sid):
    fields=[]
    for side in ('start','end'):
        for key in ('id','street','section','end'):
            node=g.node('GeometryNodeInputNamedAttribute');node.data_type='INT'
            node.inputs['Name'].default_value='st_ps_category_'+side+'_'+key
            fields.append(c.V(g,node.outputs['Exists']))
    present=_compare(g,c._stat(g,spans,sum(fields)),len(fields))
    read=lambda key:c._read(g,spans,'st_ps_'+key,span,'INT')
    # Reverse is the attached junction's authored end: the far terminal is
    # at the opposite end. Metadata indices remain integer identity fields.
    far=lambda key:c.choose(g,reverse,read('category_start_'+key),read('category_end_'+key),'INT')
    jid,peer_street,peer_section,peer_end=[far(k) for k in ('id','street','section','end')]
    first,last,count,edge_start=[read(k) for k in ('first','last','count','edge_start')]
    terminal=c.choose(g,reverse,first,last,'INT')
    expected=c.choose(g,reverse,0,count-1.,'INT')
    edge=edge_start+c.choose(g,reverse,first,last-1.,'INT')
    own_section=c.choose(g,reverse,read('first_section'),read('last_section'),'INT')
    edge_section=boundary._edge_sample(g,sources,c.named(g,'st_section_id','INT'),edge,'INT')
    edge_street=boundary._edge_sample(g,sources,c.named(g,'st_street_id','INT'),edge,'INT')
    result=present*_compare(g,role,5)*_compare(g,owner,jid)*_compare(g,jid,0,'GREATER_EQUAL')
    result=result*_compare(g,next_section,peer_section)*_compare(g,peer_section,0,'GREATER_EQUAL')
    result=result*_compare(g,peer_street,0,'GREATER_EQUAL')*(1.-_compare(g,peer_street,sid))
    result=result*(_compare(g,peer_end,0)+_compare(g,peer_end,1))*(1.-_compare(g,peer_section,own_section))
    result=result*_compare(g,terminal,expected)*_compare(g,count,2,'GREATER_EQUAL')
    return result*_compare(g,own_section,edge_section)*_compare(g,sid,edge_street)
